import unittest
from decimal import Decimal

from ledger.money import parse_amount
from ledger.report import month_of, monthly_totals


class MoneyTest(unittest.TestCase):
    def test_plain(self):
        self.assertEqual(parse_amount("300"), Decimal("300.00"))

    def test_thousands_separator(self):
        self.assertEqual(parse_amount("NT$1,234.5"), Decimal("1234.50"))

    def test_negative_forms(self):
        self.assertEqual(parse_amount("-300"), Decimal("-300.00"))
        self.assertEqual(parse_amount("(45)"), Decimal("-45.00"))


class ReportTest(unittest.TestCase):
    ENTRIES = [
        {"date": "2026-03-07", "category": "Food", "amount": "NT$1,200"},
        {"date": "2026-03-21", "category": "food", "amount": "300"},
        {"date": "2026-03-22", "category": "Food", "amount": "(100)"},
        {"date": "2026-04-02", "category": "Rent", "amount": "15,000"},
    ]

    def test_month(self):
        self.assertEqual(month_of("2026-03-07"), "2026-03")

    def test_totals(self):
        self.assertEqual(monthly_totals(self.ENTRIES), {
            ("2026-03", "food"): Decimal("1400.00"),
            ("2026-04", "rent"): Decimal("15000.00"),
        })


if __name__ == "__main__":
    unittest.main()
